import json
from datetime import datetime

with open('/app/summary.json', 'r') as f:
    summary = json.load(f)
with open('/app/charts.json', 'r') as f:
    charts = json.load(f)

# Derived stats for narrative
leo_count = summary['regime_counts']['LEO']
meo_count = summary['regime_counts']['MEO']
geo_count = summary['regime_counts']['GEO']
heo_count = summary['regime_counts']['HEO']
starlink_pct = summary['starlink_count'] / summary['total_satellites'] * 100
non_starlink = summary['total_satellites'] - summary['starlink_count']
launch_counts = summary['launch_year_counts']
peak_year = max(launch_counts, key=launch_counts.get)
peak_val = launch_counts[peak_year]
pre_2020 = summary['total_satellites'] - summary['since_2020']

# Top constellations excluding Other
top_const = [(k,v) for k,v in summary['constellation_counts'].items() if k != 'Other'][:5]

html = f'''<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Active Satellites in Earth Orbit — 2026 Catalog Analysis</title>
<style>
  :root {{
    --primary: #1f4e79;
